function moduleIcon(l){
 const title=normalize(l.title);
 if(l.skill==='Writing Task 1')return /pie/.test(title)?'pie':/process/.test(title)?'flow':/map/.test(title)?'map':'chart';
 if(l.skill==='Writing Task 2')return /discuss/.test(title)?'discuss':/causes|problem|solution/.test(title)?'idea':'writing';
 return l.skill;
}
const baseLessonRow=row;
row=function(l,current=false){return baseLessonRow(l,current).replace(/<span class="lesson-number[^>]*>.*?<\/span>/,`<span class="lesson-number module-symbol ${completed(l)?'done':''}" aria-label="${completed(l)?'Đã hoàn thành':esc(l.skill)}">${completed(l)?'✓':icon(moduleIcon(l))}</span>`);};
const worldNav={home:'Trang chủ',path:'Lộ trình',courses:'Khóa học',library:'Từ vựng',tests:'Luyện đề',writing:'Luyện viết',speaking:'Luyện nói',pet:'Justin Mini',knowledge:'Tra cứu',review:'Ôn lại',settings:'Cá nhân'};
const coreApi=api;
api=async function(url,body){const result=await coreApi(url,body);if(state&&result._world){const previous=state.ecosystem||{},before=previous.balance||0;state.ecosystem=result._world;delete result._world;if(state.ecosystem.balance>before){const changed=Object.entries(state.ecosystem.rewards).find(([key,r])=>r.stars>(previous.rewards?.[key]?.stars||0));emotion('proud',4,2200);if(changed)announceReward(changed[1],state.ecosystem.balance-before);else toast('Đã nhận '+(state.ecosystem.balance-before)+' xu từ hoạt động học.');}}return result;};
function announceReward(r,coins){
 document.querySelector('.reward-reveal')?.remove();const box=document.createElement('aside');box.className='reward-reveal';box.setAttribute('role','status');box.innerHTML=`<img src="assets/expressions/proud.png" alt="Justin Mini ăn mừng"><div><strong>${esc(r.label)}</strong><span class="earned-stars" aria-label="${r.stars} sao">${Array.from({length:3},(_,i)=>`<i style="--star-delay:${i*130}ms" class="${i<r.stars?'earned':''}" aria-hidden="true">${i<r.stars?'★':'☆'}</i>`).join('')}</span><small>+${coins} xu đã lưu vào túi</small><a href="#pet">Ghé nhà Justin</a></div><button type="button" aria-label="Đóng phần thưởng">×</button>`;document.body.append(box);box.querySelector('button').onclick=()=>box.remove();setTimeout(()=>box.remove(),7000);
}
document.querySelector('nav').innerHTML=Object.entries(worldNav).map(([id,label])=>`<a href="#${id}" data-nav="${id}" title="${label}">${icon(id)}<span>${label}</span></a>`).join('');
document.querySelector('.profile').innerHTML='<span class="online-toggle" id="online-status" role="status" hidden><span class="online-led"></span><span id="online-text">Online</span></span><a href="#settings" class="avatar" aria-label="Hồ sơ cá nhân">QA</a>';
const worlds=[['fire','Đảo Lửa','Listening','Luyện nghe'],['ice','Đảo Băng','Reading','Luyện đọc'],['thunder','Đảo Sấm','Writing Task 1','Viết Task 1'],['nature','Đảo Thiên Nhiên','Writing Task 2','Viết Task 2']];
function islandState(theme,skill){const ls=catalog.lessons.filter(l=>l.course==='combined'&&l.skill===skill),done=ls.filter(completed).length,total=ls.length;return {ls,done,total,level:done===total?3:done>=Math.ceil(total/2)?2:done>0?1:0};}
function islandMarkup(theme,name,skill,small=false){
 const p=islandState(theme,skill),phase=['Đang chờ khám phá','Trạm học đầu tiên','Nửa chặng đã mở','Cột mốc hoàn thành'][p.level],scene=p.level<2?`island-${theme}-stage-${p.level}`:`island-${theme}`;
 return `<div class="island-scene ${theme} level-${p.level} ${small?'island-small':''}" aria-label="${name}: ${phase}"><img src="assets/${scene}.webp" alt="${name}: ${phase}, ${theme==='fire'?'núi lửa và dòng dung nham':theme==='ice'?'hồ băng và cây tuyết':theme==='thunder'?'mây và pha lê sấm': 'rừng xanh và thác nước'}" loading="lazy"><div class="island-mist" aria-hidden="true"></div><span class="world-beacon" aria-hidden="true">${icon('coin')}</span>${p.level===3?'<img class="island-justin" src="assets/expressions/proud.png" alt="Justin Mini ăn mừng">':''}</div>`;
}
const oldHome=home;
home=function(){
 oldHome();
 $('.qa-hero-copy p').innerHTML='Cùng Justin Mini học IELTS theo nhịp của bạn.<br>Mỗi bài học mở thêm một góc của thế giới nhỏ.';
 $('.art-caption').textContent='Justin Mini · cùng bạn từng bước';
 $('.qa-hero-art img').alt='Justin Mini xanh biển chào bạn';
 $('.speaking-note').innerHTML='<a href="#speaking" class="text-link">'+icon('speaking')+' Luyện nói: ghi âm, nghe lại và tự nhận xét</a>';
 const e=state.ecosystem;
 const strip=document.createElement('section');strip.className='today-world';strip.innerHTML=`<a class="world-companion" href="#pet"><img src="assets/expressions/${e?.mood||'happy'}.png" alt="Justin Mini"><span><strong>Ghé nhà Justin Mini</strong><small>${e?.balance||0} xu · ${e?.streak||0} ngày học liên tiếp</small></span><b aria-hidden="true">›</b></a><div class="world-daily"><span>Những bước nhỏ hôm nay</span><strong>${e?.todayQualified?'Bạn đã có một ngày học ý nghĩa.':'Học một bài hoặc ôn 5 từ để ghi nhận ngày học.'}</strong><a href="#pet" class="text-link">Xem sao và phần thưởng</a></div>`;
 $('.home-greeting').after(strip);
 $('.home-journey').innerHTML=`<div class="journey-title"><h2>Thế giới lớn lên cùng bạn.</h2><p>Hoàn thành bài đầu tiên, nửa chặng và cả chặng để thay đổi cảnh đảo.</p><a href="#path" class="text-link">Mở bản đồ và lịch học</a></div><div class="home-islands">${worlds.map(([theme,name,skill])=>`<a href="#path">${islandMarkup(theme,name,skill,true)}<strong>${name}</strong><small>${islandState(theme,skill).done}/${islandState(theme,skill).total} bài</small></a>`).join('')}</div>`;
};
path=function(){
 calendarPath();
 const selected=Math.max(0,worlds.findIndex(([, ,skill])=>islandState('',skill).done<islandState('',skill).total));
 const map=document.createElement('section');map.className='element-map';map.innerHTML=`<div class="map-title"><div><h2>Bốn miền. Một hành trình.</h2><p>Mỗi miền thay đổi sau bài đầu tiên, nửa chặng và khi bạn hoàn thành cả chặng.</p></div><span class="map-legend">${icon('coin')} Tiến độ học thật</span></div><div class="element-islands">${worlds.map(([theme,name,skill,label],i)=>{const p=islandState(theme,skill);return `<button class="element-node ${theme}" data-world="${i}" aria-pressed="${i===selected}">${islandMarkup(theme,name,skill)}<span class="world-node-title">${name}</span><strong>${icon(skill)} ${label}</strong><span>${p.done}/${p.total} bài · ${['Chưa bắt đầu','Bài đầu tiên','Nửa chặng','Hoàn thành'][p.level]}</span><span class="progressbar"><span style="width:${p.done/p.total*100}%"></span></span></button>`;}).join('')}</div><div class="milestone-detail" id="world-detail"></div>`;
 $('.page-heading').after(map);
 function choose(i){const [theme,name,skill]=worlds[i],p=islandState(theme,skill);map.querySelectorAll('[data-world]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.world)===i));const half=Math.ceil(p.total/2);$('#world-detail').innerHTML=`<div class="world-detail-heading"><div><h3>${name} · ${esc(skill)}</h3><p>${p.level===3?'Cả hòn đảo đã bừng sáng. Bạn đã hoàn thành chặng này!':p.level===0?'Bài đầu tiên sẽ thắp sáng đảo và mở cờ hành trình.':p.level===1?`Còn ${half-p.done} bài để mở nửa chặng: sương tan, cảnh vật phát triển.`:`Còn ${p.total-p.done} bài để mở huy hiệu và đón Justin Mini.`}</p></div><span class="star-rules">1 sao: hoàn thành<br>2 sao: thêm ghi chú ≥80 ký tự<br>3 sao: bài tập đúng ≥80% nếu có</span></div><div class="milestone-steps">${[[1,'Thắp sáng'],[half,'Phát triển'],[p.total,'Bừng sáng']].map(([n,label])=>`<span class="${p.done>=n?'reached':''}">${p.done>=n?'✓':'○'} ${label} · ${n} bài</span>`).join('')}</div><div class="stage-lessons">${p.ls.map(l=>`<a href="#lesson/${l.id}"><span class="stage-status">${completed(l)?'✓':icon(moduleIcon(l))}</span><span>${esc(l.title)}<small>${completed(l)?'Đã hoàn thành':minutes(l.duration)}</small></span><b aria-hidden="true">›</b></a>`).join('')}</div>`;}
 map.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.world)));choose(selected);
};
vocabArt=function(w){
 if(w.illustration?.reviewed&&/^assets\/vocab\/cards\/[a-f0-9]{16}\.webp$/.test(w.illustration.src))return `<figure class="card-art"><img class="vocab-scene" src="${esc(w.illustration.src)}" alt="${esc(w.illustration.alt)}"><figcaption>Minh họa riêng cho cụm từ này</figcaption></figure>`;
 if(/reach a consensus/i.test(w.term))return '<figure class="card-art"><img class="vocab-scene" src="assets/consensus.png" alt="Đồng nghiệp thảo luận và thống nhất kế hoạch" loading="lazy"><figcaption>Hình minh họa: cùng đi đến thỏa thuận</figcaption></figure>';
 const n=Number(w.topic.match(/\d+/)?.[0]||1);
 const alts={1:'Chủ cửa hàng lắng nghe và xem xét nhu cầu khách hàng',2:'Hai người trò chuyện và lắng nghe nhau',3:'Cảnh sát hỗ trợ người dân',4:'Nghệ sĩ vẽ tranh trong xưởng',5:'Giáo viên hướng dẫn học sinh',6:'Gia đình đọc sách cùng con',7:'Chuẩn bị bữa ăn cân bằng',8:'Người dân trao đổi với đại diện cộng đồng',9:'Bác sĩ kiểm tra sức khỏe',10:'Quay một quảng cáo',11:'Tập trung đọc một cuốn sách',12:'Hàng xóm cùng chăm vườn',13:'Phi hành gia khám phá Mặt Trăng',14:'Bạn bè chạy bộ trong công viên',15:'Lập trình và sử dụng ứng dụng',16:'Du khách xem bản đồ cùng hướng dẫn viên',17:'Trồng cây và tái chế',18:'Đi lại bằng xe buýt và xe đạp',19:'Đồng nghiệp bàn công việc'};
 return `<figure class="card-art"><img class="vocab-scene" src="assets/vocab/topic-${n}.webp" alt="${alts[n]}" loading="lazy"><figcaption>${n===1&&w.number==='1'?'Hành động: xem xét nhu cầu trước khi quyết định':'Hình gợi ngữ cảnh chủ đề · không phải định nghĩa của từng từ'}</figcaption></figure>`;
};
const oldLibrary=library;
library=function(){oldLibrary();const b=document.createElement('a');b.className='button secondary';b.href='#vocab-practice';b.innerHTML=icon('tests')+' Luyện từ qua câu hỏi';$('.deck-sidebar').append(b);};
function itemArt(id){if(['apple','cookie','icecream','pizza','cake','greens'].includes(id))return `<img class="food-art" src="assets/food/${id}.svg" alt="Món ăn cho Justin" width="64" height="64">`;
 const arts={berry:'<path fill="#ee776c" d="M14 22q-8 3-7 13l17 20 17-20q1-10-7-13z"/><path fill="#459777" d="m24 25-9-9 9 3 9-3z"/><g fill="#ffe9b5"><circle cx="18" cy="32" r="1.5"/><circle cx="30" cy="32" r="1.5"/><circle cx="24" cy="40" r="1.5"/></g>',fish:'<path fill="#efc579" stroke="#bb8142" stroke-width="2" d="M40 28 51 19v26l-11-9c-22 20-36-7-15-14q8-2 15 6z"/><circle cx="21" cy="30" r="2" fill="#17365d"/><path d="m30 26-3 8 6 5" fill="none" stroke="#bb8142" stroke-width="2"/>',scarf:'<path fill="#eb8068" d="M12 17q12 9 28 0l5 9q-8 8-24 7l7 21-10 3-9-32z"/><path stroke="#b74339" d="M23 28h18M17 49l8-2" stroke-width="3"/>',cap:'<path fill="#1d6489" d="m9 35 5-21 15-6 15 8 4 19z"/><path fill="#183654" d="M5 35h49v8H5z"/><path fill="#f5cf77" d="m29 18 3 6 6 1-5 4 2 6-6-3-6 3 2-6-5-4 6-1z"/>',lagoon:'<path fill="#74c9b9" d="M30 8c-3 10-18 16-18 29a18 18 0 0 0 36 0C48 24 32 18 30 8z"/><path d="M22 42q8 7 17-2" fill="none" stroke="#edf9f5" stroke-width="4"/>',plant:'<path fill="#429780" d="M29 32Q8 29 13 12q18-1 18 19Q34 8 50 11q2 16-20 22"/><path d="M30 29v14" stroke="#377660" stroke-width="3"/><path fill="#e58a68" d="m16 38 4 19h20l4-19z"/>',lamp:'<path fill="#f7d892" d="M20 8h20l9 24H11z"/><path stroke="#8a6d46" stroke-width="4" d="M30 32v21m-13 2h26"/>'};
 return `<svg class="item-art" viewBox="0 0 60 64" role="img" aria-label="${esc(catalog.shop.find(i=>i.id===id)?.name||id)}">${arts[id]||''}</svg>`;
}
const illustratedVocab=vocabArt;
vocabArt=function(w){const p=w.phonetics;return illustratedVocab(w)+(p?`<details class="phonetic-details"><summary>IPA tham khảo · từng từ (Anh Mỹ)</summary><p lang="en">${p.words.map(x=>`${esc(x.word)} ${x.ipa?'/'+esc(x.ipa)+'/':'(chưa có phiên âm)'}`).join(' · ')}</p><small>Nguồn: ${p.source}. Chuyển đổi tự động từ CMUdict; cần đối chiếu từ điển khi học trọng âm. Không phải phiên âm nối âm của cả cụm.</small></details>`:'');};
function petMarkup(e,preview){const eq=preview||e.equipped||{};return `<div class="pet-figure ${eq.skin==='lagoon'?'skin-lagoon':''}"><img class="pet-body" src="assets/expressions/${e.mood||'happy'}.png" alt="Justin Mini ${esc(e.mood||'vui vẻ')}">${eq.hat?`<div class="pet-hat">${itemArt(eq.hat)}</div>`:''}${eq.outfit?`<div class="pet-scarf">${itemArt(eq.outfit)}</div>`:''}</div>`;}
function pet(){
 const e=state.ecosystem,eq=e.equipped;let busy=false;
 $('#app').innerHTML=heading('Nhà của Justin Mini','Học một chút, chăm bạn nhỏ, mở thêm những điều mới.',`<span class="coin-balance">${icon('coin')} ${e.balance} Justin Coins</span>`)+`<div class="pet-layout"><section class="pet-room ${eq.decor||''}"><div class="room-window"><img src="assets/island-nature.webp" alt="Vườn xanh bên cửa sổ"></div><div class="room-rail" aria-hidden="true"></div><div class="room-rug" aria-hidden="true"></div><button class="pet-touch" id="pet-touch" aria-label="Chạm để Justin Mini phản ứng">${petMarkup(e)}</button><div class="room-decor">${eq.decor?itemArt(eq.decor):''}</div><div class="pet-speech" role="status" id="pet-speech">${e.todayQualified?'Bạn đã dành thời gian học hôm nay. Mình vui lắm!':'Mình cùng học một chút rồi về đây nghỉ nhé!'}</div><div class="room-controls"><button class="button secondary" id="pet-feed">${itemArt('berry')} Cho ăn (${e.inventory.berry||0})</button><button class="button secondary" id="pet-rest">Nghỉ ngơi</button></div></section><aside class="pet-daily panel"><h2>Hôm nay của chúng mình</h2><p>${e.streak} ngày học liên tiếp · Asia/Taipei</p><div class="daily-goal ${e.todayQualified?'reached':''}">${e.todayQualified?'✓ Đã ghi nhận ngày học':'○ Hoàn thành một bài hoặc ôn 5 từ khác nhau'}</div><a href="#courses" class="button full">Học một bài</a><a href="#library" class="button secondary full">Ôn từ đến hạn</a><h3>Quy tắc nhận xu</h3><p>1 sao: 10 xu<br>2 sao: 20 xu<br>3 sao: 35 xu</p><small>Mỗi bài chỉ nhận thêm chênh lệch khi đạt mức sao cao hơn. Ôn 5 / 10 / 20 từ khác nhau trong ngày nhận 1 / 2 / 3 sao. Không có tiền thật.</small><a href="#rewards" class="text-link">Xem thành tích và lịch sử xu</a></aside></div><section class="shop-section"><div class="section-head"><div><h2>Một món quà nhỏ cho Justin</h2><p>Thử trước, chọn sau. Những món đã có sẽ ở lại trong kho của bạn.</p></div><button class="pill" id="shop-owned">Chỉ xem vật phẩm đã có</button></div><div class="shop-grid" id="shop-grid"></div></section>`;
 async function act(payload,label){if(busy)return;busy=true;try{await api('/api/pet',{...payload,requestId:crypto.randomUUID()});await refresh();pet();const figure=$('.pet-figure');figure?.classList.add('pet-reaction');$('#pet-speech').textContent=label;toast(label);}catch(err){toast(err.message);}finally{busy=false;}}
 $('#pet-touch').onclick=()=>act({action:'tap'},'Justin Mini: mình nghe đây!');$('#pet-feed').onclick=()=>act({action:'use',item:'berry'},'Justin Mini vui vẻ nhận dâu. Đã trừ một quả trong kho.');$('#pet-rest').onclick=()=>act({action:'rest'},'Justin Mini đang nghỉ ngơi. Bạn cũng nhớ nghỉ nhé.');
 let owned=false;
 function shop(){const fresh=state.ecosystem;$('#shop-grid').innerHTML=catalog.shop.filter(i=>!owned||fresh.inventory[i.id]).map(i=>{const n=fresh.inventory[i.id]||0,active=fresh.equipped[i.category]===i.id;return `<article class="shop-item">${itemArt(i.id)}<h3>${i.name}</h3><p>${i.detail}</p><span>${n?`Đã có · ${n} món`:i.price+' xu'}</span><div><button class="text-link" data-preview="${i.id}">Xem trước</button>${active?`<button class="button secondary small" data-remove="${i.category}">Tháo</button>`:n?`<button class="button small" data-use="${i.id}">${i.category==='food'?'Cho ăn':'Sử dụng'}</button>`:`<button class="button small" data-buy="${i.id}" ${fresh.balance<i.price?'disabled':''}>Đổi ${i.price} xu</button>`}</div></article>`;}).join('')||'<p>Kho chưa có món trong mục này.</p>';document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>act({action:'buy',item:b.dataset.buy},'Đã đổi xu và thêm vật phẩm vào kho.'));document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>act({action:'use',item:b.dataset.use},'Justin Mini đã dùng vật phẩm.'));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>act({action:'remove',category:b.dataset.remove},'Đã tháo vật phẩm.'));document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{const i=catalog.shop.find(x=>x.id===b.dataset.preview);const dialog=document.createElement('dialog');dialog.className='preview-dialog';dialog.innerHTML=`<h2>Thử ${i.name}</h2><div class="preview-pet">${i.category==='food'||i.category==='decor'?itemArt(i.id):petMarkup(fresh,{...fresh.equipped,[i.category]:i.id})}</div><p>${i.detail}</p><p>Xem trước không trừ xu và không thay đổi lựa chọn đã lưu.</p><button class="button full">Đóng xem trước</button>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('button').onclick=()=>{dialog.close();dialog.remove();};dialog.addEventListener('cancel',()=>dialog.remove(),{once:true});});}
 $('#shop-owned').onclick=()=>{owned=!owned;$('#shop-owned').setAttribute('aria-pressed',owned);shop();};shop();
}
function rewards(){const e=state.ecosystem;$('#app').innerHTML=heading('Những điều mình đã làm được','Sao từ hoạt động học; xu từ giao dịch đã được lưu.',`<a class="button secondary" href="#pet">Về nhà Justin</a>`)+`<section class="reward-overview"><img src="assets/expressions/proud.png" alt="Justin Mini tự hào"><div><h2>${e.balance} xu trong túi</h2><p>${Object.values(e.rewards).reduce((a,r)=>a+r.stars,0)} sao · ${e.streak} ngày học liên tiếp</p><p>Sao Writing và Speaking là sao hoàn thành, không phải điểm chất lượng hay band IELTS.</p></div></section><div class="reward-list">${Object.entries(e.rewards).map(([token,r])=>`<article><span class="reward-stars" aria-label="${r.stars} sao">${'★'.repeat(r.stars)}${'☆'.repeat(3-r.stars)}</span><strong>${esc(r.label)}</strong><small>${new Date(r.date*1000).toLocaleDateString('vi-VN')}</small></article>`).join('')||'<div class="empty">Hoàn thành một bài hoặc ôn 5 từ để nhận sao đầu tiên.</div>'}</div><section class="panel ledger"><h2>Lịch sử xu</h2>${[...e.ledger].reverse().map(r=>`<div><span>${esc(r.label)}<small>${new Date(r.date*1000).toLocaleString('vi-VN')}</small></span><b>${r.amount>0?'+':''}${r.amount}</b></div>`).join('')||'<p>Chưa có giao dịch.</p>'}</section>`;}
function settings(){const s=state.settings;$('#app').innerHTML=heading('Không gian của bạn','Lưu trên máy này. Bạn có thể học với nhịp vừa sức.')+`<div class="settings-layout"><form class="panel" id="settings-form"><h2>Hồ sơ học tập</h2><label class="field">Tên hiển thị<input id="profile-name" maxlength="60" value="${esc(s.name)}" required></label><label class="check-line"><input type="checkbox" id="motion-enabled" ${s.motion?'checked':''}> Cho phép chuyển động nhẹ</label><p>Cài đặt giảm chuyển động của hệ điều hành luôn được ưu tiên.</p><button class="button">Lưu cài đặt</button><p id="settings-status" role="status"></p></form><section class="panel"><h2>Online và thời gian học</h2><p>Online tính thời gian tab đang hiển thị và cửa sổ có tiêu điểm. Nhiều tab không cộng trùng.</p><p>Thời gian được ghi nhận tự động sau khi đăng nhập. Chu kỳ 24 giờ bắt đầu từ lần ghi nhận đầu tiên, được lưu trên máy chủ; không reset lúc 00:00. Ngày học liên tiếp dùng ngày lịch Asia/Taipei.</p><p id="online-details"></p><h3>Dữ liệu & kết nối</h3><p>Tiến trình lưu trên laptop khi chưa đăng nhập. Đăng nhập tài khoản để đồng bộ các thiết bị; video/PDF gốc và bản ghi âm nói vẫn ở thiết bị hiện tại.</p><p id="ai-settings-status">Đang kiểm tra kết nối AI…</p><a href="#knowledge" class="text-link">Tra cứu tài liệu gốc</a></section></div>`;$('#settings-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/api/settings',{name:$('#profile-name').value,motion:$('#motion-enabled').checked});await refresh();applySettings();$('#settings-status').textContent='Đã lưu cài đặt.';}catch(e){$('#settings-status').textContent=e.message;}};api('/api/ai-status').then(r=>{if($('#ai-settings-status'))$('#ai-settings-status').textContent=r.configured?'AI đã có cấu hình trên máy chủ.':'AI chưa kết nối: cần OPENAI_API_KEY và OPENAI_MODEL trên máy chủ. Tra cứu cục bộ vẫn hoạt động.';});renderOnline(state.onlineStatus);}
function applySettings(){document.body.classList.toggle('reduce-motion',state.settings?.motion===false);$('.avatar').textContent=(state.settings?.name||'QA').split(' ').map(x=>x[0]).slice(-2).join('').toUpperCase();}
function sourceMarkup(s){return `<article class="source-excerpt"><a href="${s.href?.startsWith('/tutor-guide.html#')?esc(s.href):'/media/'+esc(s.id)+'#page='+s.page}" target="_blank" rel="noopener">${esc(s.title)} · trang ${s.page}</a><p>${esc(s.text)}</p></article>`;}
function knowledgeView(){
 $('#app').innerHTML=heading('Có nguồn. Hiểu rõ hơn.','Tìm phương pháp, ví dụ và cách dùng từ ngay trong học liệu của bạn.')+`<form class="knowledge-search panel" id="knowledge-search"><label class="field">Bạn muốn tìm điều gì?<input id="knowledge-query" required maxlength="2000" placeholder="Ví dụ: opinion, vertical farms, environment…"></label><label class="field">Phạm vi<select id="knowledge-scope"><option value="">Tất cả học liệu</option>${catalog.lessons.map(l=>`<option value="${l.id}">${esc(l.title)}</option>`).join('')}</select></label><button class="button">Tìm trong tài liệu</button></form><p id="knowledge-index" class="small-note">Đang đọc thông tin kho tài liệu…</p><section id="knowledge-results" aria-live="polite"><div class="knowledge-empty"><img src="assets/expressions/thinking.png" alt="Justin Mini suy nghĩ"><h2>Thử tìm bằng một cụm trong bài học.</h2><p>Tên dạng bài hoặc từ khóa tiếng Anh thường giúp tìm đúng đoạn hơn.</p></div></section>`;
 api('/api/knowledge-status').then(r=>{if($('#knowledge-index'))$('#knowledge-index').textContent=`${r.documents} tài liệu · ${r.chunks} trích đoạn có số trang · Tra cứu tại máy này.`;});
 $('#knowledge-search').onsubmit=async ev=>{ev.preventDefault();const target=$('#knowledge-results');target.innerHTML='<p>Đang tìm trong học liệu…</p>';try{const r=await api('/api/knowledge',{query:$('#knowledge-query').value,lesson:$('#knowledge-scope').value||null});if(!target.isConnected)return;target.innerHTML=r.sources.map(sourceMarkup).join('')||'<div class="empty">Chưa tìm thấy đoạn phù hợp. Thử cụm tiếng Anh ngắn hơn hoặc chọn tất cả học liệu.</div>';}catch(e){target.textContent=e.message;}};
}
function vocabPractice(){
 let words=catalog.vocab.filter(w=>w.translation_vi).sort(()=>0.5-Math.random()).slice(0,10),index=0,correct=0,mode='meaning';
 $('#app').innerHTML=heading('Chơi với từ. Nhớ bằng cách dùng.','10 câu ngắn; kết quả luyện tập riêng với lịch ôn flashcard.',`<a class="button secondary" href="#library">Về flashcard</a>`)+`<div class="filters">${[['meaning','Chọn nghĩa'],['listen','Nghe chọn từ'],['write','Viết từ theo nghĩa'],['sentence','Điền từ vào ví dụ']].map(([v,n])=>`<button data-vmode="${v}" class="pill ${v===mode?'selected':''}">${n}</button>`).join('')}</div><section class="panel vocab-game" id="vocab-game"></section>`;
 function draw(){const w=words[index];if(!w){$('#vocab-game').innerHTML=`<img src="assets/expressions/proud.png" alt="Justin Mini vui vẻ"><h2>${correct}/10 câu đúng</h2><p>Đây là kết quả luyện nhanh, không tự tăng mức ghi nhớ.</p><a href="#library" class="button">Ôn lại với flashcard</a>`;return;}
 const choices=[w,...catalog.vocab.filter(x=>x.id!==w.id&&x.translation_vi).sort(()=>.5-Math.random()).slice(0,3)].sort(()=>.5-Math.random());
 const needle=w.term.replace(/^to /i,'').split('/')[0].trim(),gap=vocabGap(w),sentence=gap?.sentence||w.translation_vi;
 $('#vocab-game').innerHTML=`<span class="chip">Câu ${index+1}/10</span>${vocabArt(w)}<h2>${mode==='meaning'?esc(w.term):mode==='listen'?'Nghe và chọn cụm vừa được đọc':mode==='write'?esc(w.translation_vi):esc(sentence===w.example_en?w.translation_vi:sentence)}</h2>${mode==='listen'?'<button class="button secondary" id="game-listen">Nghe lại</button>':''}<form id="game-answer">${mode==='meaning'||mode==='listen'?choices.map(x=>`<label class="game-choice"><input type="radio" name="game-choice" value="${x.id}" required> ${esc(mode==='meaning'?x.translation_vi:x.term)}</label>`).join(''):'<label class="field">Cụm từ tiếng Anh<input id="game-text" required autocomplete="off"></label>'}<button class="button">Kiểm tra</button></form><div id="game-feedback" role="status"></div>`;
 if(mode==='listen')$('#game-listen').onclick=()=>{if(!('speechSynthesis'in window))return toast('Thiết bị chưa hỗ trợ giọng đọc.');const u=new SpeechSynthesisUtterance(w.term);u.lang='en-GB';speechSynthesis.cancel();speechSynthesis.speak(u);};
 $('#game-answer').onsubmit=ev=>{ev.preventDefault();const given=mode==='meaning'||mode==='listen'?document.querySelector('[name=game-choice]:checked').value:normalize($('#game-text').value.trim()),ok=mode==='meaning'||mode==='listen'?given===w.id:(mode==='sentence'&&gap?[gap.answer]:[w.term,needle]).map(normalize).includes(given);if(ok)correct++;$('#game-feedback').innerHTML=`<h3>${ok?'✓ Chính xác':'Cùng xem lại nhé'}</h3><p>${mode==='sentence'&&gap?'Từ cần điền: '+esc(gap.answer)+' · ':''}${esc(w.term)} — ${esc(w.translation_vi)}</p><p>${esc(w.example_en)}</p><button class="button" id="game-next">Câu tiếp theo</button>`;$('#game-answer').querySelectorAll('input,button').forEach(x=>x.disabled=true);$('#game-next').onclick=()=>{index++;draw();};};
 }
 document.querySelectorAll('[data-vmode]').forEach(b=>b.onclick=()=>{mode=b.dataset.vmode;words=catalog.vocab.filter(w=>w.translation_vi&&(mode!=='sentence'||vocabGap(w))).sort(()=>.5-Math.random()).slice(0,10);index=0;correct=0;document.querySelectorAll('[data-vmode]').forEach(x=>x.classList.toggle('selected',x===b));draw();});draw();
 const extra=document.createElement('div');extra.className='practice-links';extra.innerHTML='<a href="#vocab-images">Nhìn hình chọn từ</a><a href="#vocab-matching">Ghép từ với nghĩa</a><a href="#vocab-context">Học từ trong câu</a>';$('.filters').after(extra);
 cleanup=()=>{if('speechSynthesis'in window)speechSynthesis.cancel();};
}
function vocabGap(w){const candidates=(w.term.match(/[A-Za-z]+/g)||[]).filter(t=>t.length>3&&!['something','someone'].includes(t.toLowerCase())).sort((a,b)=>b.length-a.length);for(const t of candidates){const pattern=new RegExp('\\b'+t+'\\b','i'),match=w.example_en.match(pattern);if(match)return {answer:match[0],sentence:w.example_en.replace(pattern,'_____')};}return null;}
function vocabMatching(){
 const seen=new Set();const words=catalog.vocab.filter(w=>{if(!w.translation_vi||seen.has(w.translation_vi))return false;seen.add(w.translation_vi);return true;}).sort(()=>.5-Math.random()).slice(0,4);let left=null,right=null,attempts=0,found=new Set();
 $('#app').innerHTML=heading('Ghép một từ. Kết nối một ý.','Chọn cụm tiếng Anh, rồi chọn nghĩa tương ứng. Bạn có thể làm bằng chuột hoặc bàn phím.',`<a class="button secondary" href="#vocab-practice">Các cách luyện từ</a>`)+`<section class="panel matching-game"><div class="matching-columns"><div>${words.map(w=>`<button class="match-word" data-side="left" data-match="${w.id}">${esc(w.term)}</button>`).join('')}</div><div>${[...words].sort(()=>.5-Math.random()).map(w=>`<button class="match-word" data-side="right" data-match="${w.id}">${esc(w.translation_vi)}</button>`).join('')}</div></div><p id="matching-status" role="status">0/4 cặp đã ghép đúng</p><button class="button secondary" id="matching-again">Bộ bốn từ mới</button></section>`;
 document.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>{if(found.has(b.dataset.match))return;if(b.dataset.side==='left')left=b;else right=b;document.querySelectorAll('[data-match]').forEach(x=>x.classList.toggle('chosen',x===left||x===right));if(left&&right){attempts++;if(left.dataset.match===right.dataset.match){found.add(left.dataset.match);left.disabled=right.disabled=true;left.classList.add('matched');right.classList.add('matched');const w=words.find(x=>x.id===left.dataset.match);$('#matching-status').textContent=`✓ ${found.size}/4 cặp · ${w.term}: ${w.translation_vi}`;emotion('happy',2);}else{$('#matching-status').textContent='Chưa khớp. Thử chọn lại một cặp nhé.';emotion('encouraging',2);}left=right=null;if(found.size===4)$('#matching-status').textContent=`Đã ghép đúng 4 cặp sau ${attempts} lần thử. Xem lại với flashcard để lưu lịch ôn.`;}});$('#matching-again').onclick=vocabMatching;
}
function vocabIllustrationGame(contextMode=false){
 const terms=['To take something into consideration/ account','To reach a consensus','to be engrossed in'];
 let list=contextMode?catalog.vocab.filter(w=>w.translation_vi&&w.example_en).sort(()=>.5-Math.random()).slice(0,10):catalog.vocab.filter(w=>terms.some(t=>w.term.toLowerCase()===t.toLowerCase()||t==='to be engrossed in'&&/engrossed in/i.test(w.term)));let n=0,score=0;
 $('#app').innerHTML=heading(contextMode?'Hiểu từ trong câu.':'Nhìn một hành động. Nhớ một cụm từ.',contextMode?'Đọc ví dụ trong học liệu và chọn nghĩa của cụm từ.':'Dùng các hình đã đối chiếu hành động với từ; không đoán nghĩa từ ảnh chủ đề chung.',`<a href="#vocab-practice" class="button secondary">Các cách luyện từ</a>`)+`<section class="panel vocab-game" id="illustration-game"></section>`;
 function draw(){const w=list[n];if(!w){$('#illustration-game').innerHTML=`<h2>${score}/${list.length} câu đúng</h2><p>Kết quả luyện tập không tự cập nhật mastery.</p><a class="button" href="#library">Ôn với flashcard</a>`;return;}const choices=[w,...catalog.vocab.filter(x=>x.id!==w.id&&x.translation_vi&&!list.some(a=>a.id===x.id)).sort(()=>.5-Math.random()).slice(0,3)].sort(()=>.5-Math.random());const art=/engrossed in/i.test(w.term)?'<figure class="card-art"><img class="vocab-scene" src="assets/reading.png" alt="Justin Mini chăm chú đọc sách"></figure>':illustratedVocab(w);$('#illustration-game').innerHTML=`<span class="chip">${n+1}/${list.length}</span>${contextMode?`<h2>${esc(w.term)}</h2><blockquote lang="en">${esc(w.example_en)}</blockquote>`:art}<h2>${contextMode?'Cụm này nghĩa là gì?':'Cụm nào phù hợp với hành động chính trong hình?'}</h2><form id="illustration-answer">${choices.map(x=>`<label class="game-choice"><input type="radio" name="picture-choice" value="${x.id}" required>${esc(contextMode?x.translation_vi:x.term)}</label>`).join('')}<button class="button">Kiểm tra</button></form><div id="illustration-feedback" role="status"></div>`;$('#illustration-answer').onsubmit=ev=>{ev.preventDefault();const ok=document.querySelector('[name=picture-choice]:checked').value===w.id;if(ok)score++;$('#illustration-answer').querySelectorAll('input,button').forEach(b=>b.disabled=true);$('#illustration-feedback').innerHTML=`<h3>${ok?'✓ Chính xác':'Cùng xem lại'}</h3><p>${esc(w.term)} · ${esc(w.translation_vi)}</p><p>${esc(w.example_en)}</p><button class="button" id="illustration-next">Tiếp theo</button>`;$('#illustration-next').onclick=()=>{n++;draw();};};}draw();
}
function writingView(){
 let task='task2',draft=state.writingDrafts?.[task]||{version:0},timer,queued=Promise.resolve(),disposed=false,busy=false;
 const promptExample='When choosing a job, the salary is the most important consideration. To what extent do you agree or disagree?';
 $('#app').innerHTML=heading('Một ý rõ. Một bài viết tốt hơn.','Viết, lưu bản nháp, tự kiểm tra và nhìn lại bài của mình.')+`<div class="writing-toolbar"><div class="filters"><button class="pill" data-wtask="task1">${icon('Writing Task 1')} Task 1 · 150 từ</button><button class="pill selected" data-wtask="task2">${icon('Writing Task 2')} Task 2 · 250 từ</button></div><span id="writing-save" role="status">Chưa chỉnh sửa</span><span id="writing-count">0 từ</span></div><div class="writing-workspace"><aside class="panel writing-prompt"><h2>Đề và ý tưởng</h2><label class="field">Đề bài<textarea id="writing-prompt" rows="6" maxlength="4000"></textarea></label><p id="writing-source" class="small-note"></p><label class="field">Dàn ý của bạn<textarea id="writing-outline" rows="8" maxlength="10000" placeholder="Quan điểm • ý chính • ví dụ…"></textarea></label><button class="text-link" id="writing-source-open">Mở học liệu Writing</button><p class="small-note">Sao hoàn thành: 1 sao khi đủ độ dài; 2 sao khi có dàn ý ≥40 ký tự; 3 sao khi bạn xác nhận đã kiểm tra đủ 4 tiêu chí.</p></aside><section class="writing-paper"><div class="paper-top"><h2>Bài viết của bạn</h2><div><button class="pill" id="writing-timer-start">Bắt đầu 40 phút</button><span id="writing-timer">40:00</span></div></div><label class="sr-only" for="writing-text">Nội dung bài viết tiếng Anh</label><textarea id="writing-text" lang="en" spellcheck="true" maxlength="40000" placeholder="Start writing here…"></textarea><div class="writing-checks"><h3>Đọc lại trước khi hoàn thành</h3>${[['response','Trả lời đúng yêu cầu đề'],['structure','Bố cục và liên kết ý'],['vocabulary','Cách dùng từ'],['grammar','Ngữ pháp và chính tả']].map(([id,label])=>`<label><input type="checkbox" name="writing-check" value="${id}"> ${label}</label>`).join('')}</div><div class="writing-actions"><button class="button secondary" id="writing-save-now">Lưu bản nháp</button><button class="button" id="writing-submit">Lưu bài hoàn thành</button><button class="text-link" id="writing-export">Tải bài .txt</button></div><div id="writing-result" role="status"></div></section></div><section class="panel writing-history"><h2>Bài viết đã lưu</h2><div id="writing-history"></div></section>`;
 function load(t){task=t;draft=state.writingDrafts?.[task]||{version:0};$('#writing-prompt').value=draft.prompt||(task==='task2'?promptExample:'');$('#writing-outline').value=draft.outline||'';$('#writing-text').value=draft.text||'';$('#writing-count').textContent=(draft.words||0)+' từ';$('#writing-source').textContent=task==='task2'&&$('#writing-prompt').value===promptExample?'Đề từ slide Opinion, trang 6.':'Dán đề bạn muốn luyện hoặc mở tài liệu gốc để chọn đề; giữ biểu đồ gốc cho Task 1.';$('#writing-save').textContent=draft.updated?'Đã lưu '+new Date(draft.updated*1000).toLocaleTimeString('vi-VN'):'Chưa có bản nháp';$('#writing-timer-start').textContent=`Bắt đầu ${task==='task1'?20:40} phút`;$('#writing-timer').textContent=task==='task1'?'20:00':'40:00';clearInterval(timer);$('#writing-timer-start').disabled=false;document.querySelectorAll('[data-wtask]').forEach(b=>b.classList.toggle('selected',b.dataset.wtask===task));historyDraw();}
 function historyDraw(){$('#writing-history').innerHTML=(state.writingSubmissions||[]).slice().reverse().map((d,i)=>`<details><summary>${d.task.toUpperCase()} · ${d.words} từ · ${'★'.repeat(d.stars)} · ${new Date(d.updated*1000).toLocaleString('vi-VN')}</summary><p>${esc(d.prompt)}</p><pre>${esc(d.text)}</pre></details>`).join('')||'<p>Hoàn thành một bài để lưu vào lịch sử.</p>';}
 function snapshot(){return {task,text:$('#writing-text').value,outline:$('#writing-outline').value,prompt:$('#writing-prompt').value};}
 function save(submit=false){const data=snapshot(),checks=Array.from(document.querySelectorAll('[name=writing-check]:checked'),x=>x.value);queued=queued.catch(()=>{}).then(async()=>{const previous=state.writingDrafts?.[data.task]||{version:0};const r=await api('/api/writing',{...data,version:previous.version,submit,checks});(state.writingDrafts||={})[data.task]=r;draft=r;if(!disposed&&data.task===task){$('#writing-save').textContent='Đã lưu '+new Date(r.updated*1000).toLocaleTimeString('vi-VN');if(submit){await refresh();historyDraw();$('#writing-result').innerHTML=`<div class="result"><h3>${'★'.repeat(r.stars)} Đã lưu bài hoàn thành</h3><p>Sao theo độ dài, dàn ý và checklist tự kiểm tra; chưa chấm band IELTS.</p><a href="#pet" class="text-link">Xem phần thưởng cùng Justin</a></div>`;}}return r;});return queued;}
 let saveTimer;
 for(const id of ['writing-text','writing-outline','writing-prompt'])$('#'+id).oninput=()=>{$('#writing-count').textContent=($('#writing-text').value.match(/\b[\w]+(?:['’-][\w]+)*\b/g)||[]).length+' từ';$('#writing-save').textContent='Đang lưu…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>save().catch(e=>{if(!disposed)$('#writing-save').textContent='Chưa lưu: '+e.message;}),600);};
 $('#writing-save-now').onclick=()=>{clearTimeout(saveTimer);save().catch(e=>toast(e.message));};
 $('#writing-submit').onclick=async()=>{if(busy)return;busy=true;clearTimeout(saveTimer);$('#writing-submit').disabled=true;try{await save(true);}catch(e){$('#writing-result').textContent=e.message;}finally{busy=false;if(!disposed)$('#writing-submit').disabled=false;}};
 document.querySelectorAll('[data-wtask]').forEach(b=>b.onclick=async()=>{if(busy)return;busy=true;clearTimeout(saveTimer);try{await save();load(b.dataset.wtask);}catch(e){toast(e.message);}finally{busy=false;}});
 $('#writing-source-open').onclick=()=>location.hash='#courses/'+encodeURIComponent(task==='task1'?'Writing Task 1':'Writing Task 2');
 $('#writing-timer-start').onclick=()=>{const end=performance.now()+(task==='task1'?20:40)*60000;$('#writing-timer-start').disabled=true;timer=setInterval(()=>{const remaining=(end-performance.now())/1000;$('#writing-timer').textContent=clock(remaining);if(remaining<=0){clearInterval(timer);save().catch(e=>toast(e.message));toast('Hết thời gian luyện. Bản nháp được lưu; bạn có thể đọc lại.');}},1000);};
 $('#writing-export').onclick=()=>{const blob=new Blob([$('#writing-prompt').value+'\n\n'+$('#writing-text').value],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='quynh-anh-'+task+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 load(task);
 const aiButton=document.createElement('button');aiButton.className='button secondary';aiButton.type='button';aiButton.id='writing-ai-feedback';aiButton.textContent='Nhờ AI góp ý bài viết';$('.writing-actions').append(aiButton);
 const aiInfo=document.createElement('p');aiInfo.className='small-note';aiInfo.id='writing-ai-disclosure';aiInfo.textContent='Khi bấm nhờ AI, đề và bài viết được gửi tới nhà cung cấp đã cấu hình. Nhận xét không phải điểm IELTS chính thức.';$('.writing-actions').after(aiInfo);
 aiButton.onclick=async()=>{if(busy)return;busy=true;aiButton.disabled=true;const current=snapshot();$('#writing-result').textContent='Đang đọc và góp ý bài viết…';try{await save();const result=await api('/api/writing-feedback',{...current,consent:true});if(!disposed)$('#writing-result').innerHTML='<div class="ai-writing-feedback"><h3>Nhận xét luyện tập của AI</h3><p>'+esc(result.text)+'</p></div>';}catch(err){if(!disposed)$('#writing-result').textContent=err.message;}finally{busy=false;if(!disposed)aiButton.disabled=false;}};
 cleanup=()=>{clearTimeout(saveTimer);clearInterval(timer);save().catch(e=>toast(e.message));disposed=true;};
}
function recordingDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('quynh-anh-speaking',1);request.onupgradeneeded=()=>request.result.createObjectStore('recordings',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function recordingPut(row){const db=await recordingDB();return new Promise((resolve,reject)=>{const tx=db.transaction('recordings','readwrite');tx.objectStore('recordings').put(row);tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error);};});}
async function recordingAll(){const db=await recordingDB();return new Promise((resolve,reject)=>{const tx=db.transaction('recordings');const req=tx.objectStore('recordings').getAll();req.onsuccess=()=>{db.close();resolve(req.result);};req.onerror=()=>{db.close();reject(req.error);};});}
function speakingView(){
 let stream,recorder,started=0,seconds=0,parts=[],url,blob,recordId,recordPrompt,disposed=false,timer;const urls=[];
 $('#app').innerHTML=heading('Nói thử. Nghe lại. Tự tin hơn.','Ghi âm, nghe lại và nhờ Justin nhận xét. AI hỗ trợ luyện tập, không cho band IELTS.')+`<div class="speaking-layout"><section class="panel speaking-prompt"><img src="assets/expressions/listening.png" alt="Justin Mini lắng nghe"><h2>Chọn điều bạn muốn kể</h2><label class="field">Gợi ý luyện tập tự biên soạn<select id="speaking-topic"><option>Describe a place where you enjoy studying.</option><option>Talk about a skill you would like to learn.</option><option>Describe a memorable trip.</option></select></label><label class="field">Hoặc nhập đề của bạn<textarea id="speaking-custom" maxlength="3000" rows="3"></textarea></label><p>Dành một phút ghi ý, rồi thử nói trong 1–2 phút. Đây là buổi tự luyện, không phải đề thi chính thức.</p><p class="small-note">1 sao: tự luyện ≥30 giây và lưu; 2 sao: thêm nhận xét ≥40 ký tự. Thời lượng tự luyện không dùng để đánh giá chất lượng.</p></section><section class="speaking-studio panel"><h2>Buổi luyện nói của bạn</h2><div class="recording-disc" id="recording-disc">${icon('speaking')}</div><strong id="speaking-clock">00:00</strong><p id="speaking-status" role="status">Chỉ yêu cầu micro khi bạn bấm Bắt đầu ghi âm. Âm thanh lưu trong trình duyệt này.</p><div class="recording-actions"><button class="button" id="speaking-start">Bắt đầu ghi âm</button><button class="button secondary" id="speaking-stop" disabled>Dừng ghi âm</button></div><audio id="speaking-playback" controls hidden></audio><label class="field">Mình muốn cải thiện điều gì?<textarea id="speaking-reflection" maxlength="5000" rows="4" placeholder="Từ bị lặp, chỗ ngập ngừng, một ý muốn nói rõ hơn…"></textarea></label><button class="button full" id="speaking-save" disabled>Lưu buổi luyện nói</button></section></div><section class="panel speaking-history"><h2>Nghe lại các buổi đã lưu</h2><div id="speaking-history"></div></section>`;
 async function historyDraw(){try{const records=await recordingAll();if(disposed)return;$('#speaking-history').innerHTML=records.reverse().map((r,i)=>{const u=URL.createObjectURL(r.blob);urls.push(u);return `<article><h3>${esc(r.prompt)}</h3><p>${Math.round(r.duration)} giây · ${new Date(r.date).toLocaleString('vi-VN')}</p><audio controls src="${u}"></audio><a class="text-link" href="${u}" download="speaking-${r.id}.webm">Tải ghi âm</a><p>${esc(r.reflection)}</p></article>`;}).join('')||'<p>Bản ghi sẽ xuất hiện ở đây sau khi bạn lưu. Dữ liệu âm thanh thuộc riêng trình duyệt này.</p>';}catch(e){if(!disposed)$('#speaking-history').textContent='Không mở được kho ghi âm: '+e.message;}}
 $('#speaking-start').onclick=async()=>{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('Trình duyệt chưa hỗ trợ ghi âm. Thử Chrome hoặc Edge.');$('#speaking-start').disabled=true;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(disposed){stream.getTracks().forEach(t=>t.stop());return;}parts=[];blob=null;recordPrompt=$('#speaking-custom').value.trim()||$('#speaking-topic').value;document.dispatchEvent(new CustomEvent('speaking-record-ready',{detail:null}));recordId=crypto.randomUUID();recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)parts.push(e.data);};recorder.onstop=()=>{blob=new Blob(parts,{type:recorder.mimeType});if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(blob);stream.getTracks().forEach(t=>t.stop());if(disposed)return;document.dispatchEvent(new CustomEvent('speaking-record-ready',{detail:{blob,prompt:recordPrompt}}));$('#speaking-playback').src=url;$('#speaking-playback').hidden=false;$('#speaking-save').disabled=false;$('#speaking-start').disabled=false;$('#speaking-status').textContent='Đã ghi xong. Nghe lại và ghi nhận xét trước khi lưu.';};recorder.start();started=performance.now();seconds=0;$('#speaking-stop').disabled=false;$('#recording-disc').classList.add('recording');$('#speaking-status').textContent='Đang ghi âm tại thiết bị…';timer=setInterval(()=>{seconds=(performance.now()-started)/1000;$('#speaking-clock').textContent=clock(seconds);if(seconds>=600)stop();},200);}catch(e){if(!disposed){$('#speaking-start').disabled=false;$('#speaking-status').textContent=e.name==='NotAllowedError'?'Chưa được cấp quyền micro. Bật quyền micro của trình duyệt rồi thử lại.':'Không mở được micro: '+e.message;}}};
 function stop(){if(recorder?.state==='recording'){seconds=(performance.now()-started)/1000;clearInterval(timer);recorder.stop();$('#speaking-stop').disabled=true;$('#recording-disc').classList.remove('recording');}}
 $('#speaking-stop').onclick=stop;
 $('#speaking-save').onclick=async()=>{if(!blob)return;$('#speaking-save').disabled=true;const prompt=$('#speaking-custom').value.trim()||$('#speaking-topic').value,reflection=$('#speaking-reflection').value;try{await recordingPut({id:recordId,blob,duration:seconds,prompt,reflection,date:Date.now()});await api('/api/speaking',{requestId:recordId,duration:Math.min(600,seconds),prompt,reflection});await refresh();$('#speaking-status').textContent='Đã lưu bản ghi và nhận xét. Bạn có thể nghe lại bên dưới.';historyDraw();}catch(e){$('#speaking-status').textContent='Chưa lưu đủ dữ liệu: '+e.message;$('#speaking-save').disabled=false;}};
 historyDraw();cleanup=()=>{disposed=true;clearInterval(timer);if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());if(url)URL.revokeObjectURL(url);urls.forEach(u=>URL.revokeObjectURL(u));};
}
tests=function(){
 $('#app').innerHTML=heading('Luyện có hướng dẫn. Thi khi sẵn sàng.','9 bộ Academic Reading trong học liệu của bạn, mỗi bộ 40 câu.')+`<div class="practice-mode-guide"><div>${icon('courses')}<h2>Luyện tập</h2><p>Không giới hạn giờ. Xem đề, tự chọn câu và dùng tra cứu học liệu.</p></div><div>${icon('tests')}<h2>Thi thử Reading</h2><p>60 phút trên máy chủ. Tự lưu, điều hướng câu, ẩn hỏi đáp và đáp án.</p></div></div><div class="test-grid">${catalog.tests.map(t=>{const pending=[...Object.values(state.exams||{}),...Object.values(state.writingExams||{})].find(e=>e.test===t.id&&!e.submitted);return `<section class="test-card"><div class="test-icon">${icon('Reading')}</div><h3>${esc(t.title)}</h3><p>40 câu · 3 phần · đề PDF gốc</p><a class="button full" href="#test/${t.id}/guided">${pending?'Tiếp tục phiên đang làm':'Luyện tập từng câu'}</a><a class="button secondary full" href="#test/${t.id}/exam">Thi thử 60 phút</a></section>`;}).join('')}</div><section class="panel"><h2>Các kỹ năng khác</h2><div class="practice-links"><a href="#courses/Listening">${icon('Listening')} Bài học & audio Listening</a><a href="#writing">${icon('writing')} Không gian Writing</a><a href="#speaking">${icon('speaking')} Tự luyện Speaking</a></div><p class="small-note">Kho nguồn chưa có bộ Listening chuẩn hóa đủ transcript và đáp án để mở một bài thi Listening; chưa ghép thành đề IELTS 4 kỹ năng hoàn chỉnh.</p></section><section class="panel"><h2>Lịch sử luyện tập</h2>${history(12)}</section>`;
};
test=async function(ref){
 const [id,requested='guided']=ref.split('/'),t=catalog.tests.find(t=>t.id===id);if(!t)return missing();let disposed=false,e,focus=0,saveTimer,timer,queue=Promise.resolve(),busy=false;
 $('#app').innerHTML='<div class="loading">Đang mở phiên luyện đề…</div>';cleanup=()=>{disposed=true;clearTimeout(saveTimer);clearInterval(timer);};
 try{e=await api('/api/exam-start',{id,mode:requested});if(disposed)return;}catch(err){if(!disposed)$('#app').innerHTML=`<div class="error">${esc(err.message)} <a href="#tests">Về phòng luyện đề</a></div>`;return;}
 (state.exams||={})[e.id]=e;
 if(e.submitted){await refresh();if(!disposed)location.hash='#review/'+state.attempts.findIndex(a=>a.session===e.id);return;}
 chatLauncher.hidden=e.mode==='exam';
 focus=e.focus||0;document.body.classList.toggle('exam-mode',e.mode==='exam');
 $('#app').innerHTML=`<div class="exam-header"><div><a href="#tests" class="text-link">Về phòng luyện đề</a><h1>${esc(t.title)}</h1><p>${e.mode==='exam'?'Thi thử · Hỏi đáp và đáp án bị ẩn':'Luyện tập · Không giới hạn thời gian'}</p></div><div><strong id="exam-clock"></strong><span id="exam-save" role="status">Đã mở phiên</span><button class="button" id="exam-submit">Nộp bài</button></div></div><div class="exam-workspace"><section class="exam-passage"><div class="exam-passage-top"><h2>Đề gốc của bạn</h2><a target="_blank" rel="noopener" class="text-link" href="/media/${t.paper}">Mở PDF riêng</a></div><iframe class="pdf" id="exam-pdf" title="Đề Reading gốc" src="/media/${t.paper}#page=${t.questions[focus]?.page||1}"></iframe></section><section class="exam-question"><div id="exam-question-content"></div><div class="question-actions"><button class="button secondary" id="exam-prev">Câu trước</button><button class="button secondary" id="exam-flag">Đánh dấu</button><button class="button secondary" id="exam-next">Câu sau</button></div><h3>Điều hướng câu</h3><div class="question-navigator" id="question-navigator"></div><p class="small-note">Nội dung được trích từ PDF; với bảng, sơ đồ và layout chưa xác minh, hãy dùng PDF gốc. Mỗi ô giữ số câu đúng theo đề.</p></section></div><dialog class="exam-confirm" id="exam-confirm"><h2>Nộp bài Reading?</h2><p id="exam-confirm-text"></p><div class="dialog-actions"><button class="button secondary" id="exam-cancel">Tiếp tục làm</button><button class="button" id="exam-confirm-submit">Nộp và xem kết quả</button></div></dialog>`;
 function navDraw(){$('#question-navigator').innerHTML=e.answers.map((a,i)=>`<button data-qnav="${i}" class="${i===focus?'current':''} ${a?'answered':''} ${e.flags.includes(i)?'flagged':''}" aria-label="Câu ${i+1}${a?', đã trả lời':''}${e.flags.includes(i)?', đã đánh dấu':''}" aria-current="${i===focus?'step':'false'}">${i+1}${e.flags.includes(i)?'<small>◆</small>':''}</button>`).join('');$('#exam-prev').disabled=focus===0;$('#exam-next').disabled=focus===39;$('#exam-flag').textContent=e.flags.includes(focus)?'Bỏ đánh dấu':'Đánh dấu';document.querySelectorAll('[data-qnav]').forEach(b=>b.onclick=()=>{focus=Number(b.dataset.qnav);draw();saveSoon();});}
 function draw(){const q=t.questions[focus]||{type:'text',prompt:'Đọc câu '+(focus+1)+' trong đề PDF gốc.',options:[]};let control;if(q.type==='multi')control=multiControl(q,e);else if(q.type==='tfng'||q.type==='ynng'||q.type==='mcq')control=q.options.map(o=>`<label class="exam-option"><input type="radio" name="exam-answer" value="${esc(o.value)}" ${e.answers[focus]===o.value?'checked':''}>${esc(o.label)}</label>`).join('');else if(q.type==='matching')control=`<label class="field">Ghép với phương án<select id="exam-answer"><option value="">Chưa chọn</option>${q.options.map(o=>`<option value="${esc(o.value)}" ${e.answers[focus]===o.value?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label>`;else control=`<label class="field">Đáp án câu ${focus+1}<input id="exam-answer" value="${esc(e.answers[focus])}" maxlength="500" autocomplete="off"></label>`;$('#exam-question-content').innerHTML=`<span class="chip">Câu ${focus+1}/40</span><details class="question-instructions"><summary>Yêu cầu dạng bài</summary><p>${esc(q.instructions||'Xem yêu cầu và giới hạn từ trong đề PDF gốc.')}</p></details><h2>${esc(q.prompt)}</h2>${control}<button class="text-link" id="exam-source-page">Xem trang ${q.page||1} trong PDF</button>`;$('#exam-source-page').onclick=()=>$('#exam-pdf').src='/media/'+t.paper+'#page='+(q.page||1);$('#exam-question-content').querySelectorAll('input,select').forEach(input=>input.onchange=input.oninput=()=>{if(q.type==='multi'){const selected=Array.from(document.querySelectorAll('[name=exam-multi]:checked'),x=>x.value);if(selected.length>q.group.length){input.checked=false;toast('Chỉ chọn '+q.group.length+' phương án theo đề.');return;}q.group.forEach((n,j)=>e.answers[n-1]=selected[j]||'');}else e.answers[focus]=input.value;navDraw();saveSoon();});navDraw();}
 function save(){const snapshot={session:e.id,answers:[...e.answers],flags:[...e.flags],focus};queue=queue.catch(()=>{}).then(async()=>{const r=await api('/api/exam-draft',{...snapshot,version:e.version});e.version=r.version;if(!disposed&&$('#exam-save'))$('#exam-save').textContent='Đã lưu '+new Date(r.updated*1000).toLocaleTimeString('vi-VN');});return queue;}
 function saveSoon(){clearTimeout(saveTimer);$('#exam-save').textContent='Đang lưu…';saveTimer=setTimeout(()=>save().catch(err=>{if(!disposed)$('#exam-save').textContent='Chưa lưu: '+err.message;}),400);}
 async function submit(expired=false){if(busy)return;busy=true;clearTimeout(saveTimer);$('#exam-submit').disabled=true;try{if(!expired)await save();else await queue.catch(()=>{});const result=await api('/api/exam-submit',{session:e.id});clearInterval(timer);await refresh();if(disposed)return;$('#exam-confirm').close();location.hash='#review/'+state.attempts.findIndex(a=>a.session===result.session);toast(result.expired?'Hết giờ: đã chấm bài làm được lưu trước hạn.':'Đã chấm và lưu bài Reading.');}catch(err){busy=false;if(!disposed){$('#exam-submit').disabled=false;toast(err.message);}}}
 $('#exam-prev').onclick=()=>{focus--;draw();saveSoon();};$('#exam-next').onclick=()=>{focus++;draw();saveSoon();};$('#exam-flag').onclick=()=>{e.flags=e.flags.includes(focus)?e.flags.filter(n=>n!==focus):[...e.flags,focus];navDraw();saveSoon();};
 $('#exam-submit').onclick=()=>{$('#exam-confirm-text').textContent=`Đã trả lời ${e.answers.filter(Boolean).length}/40 câu. Câu bỏ trống tính 0 điểm.`;$('#exam-confirm').showModal();};$('#exam-cancel').onclick=()=>$('#exam-confirm').close();$('#exam-confirm-submit').onclick=()=>submit();
 const timeOrigin=performance.now(),serverEstimate=e.serverNow;function tick(){const seconds=e.deadline-(serverEstimate+(performance.now()-timeOrigin)/1000);$('#exam-clock').textContent=e.mode==='exam'?clock(seconds):'Không giới hạn';if(e.mode==='exam'&&seconds<=0)submit(true);}timer=setInterval(tick,1000);draw();tick();
 const pageHide=()=>{if(!busy)navigator.sendBeacon('/api/exam-draft',new Blob([JSON.stringify({session:e.id,version:e.version,answers:e.answers,flags:e.flags,focus})],{type:'application/json'}));};window.addEventListener('pagehide',pageHide);
 cleanup=()=>{disposed=true;clearTimeout(saveTimer);clearInterval(timer);window.removeEventListener('pagehide',pageHide);$('#exam-confirm')?.remove();if(!busy)save().catch(err=>toast(err.message));document.body.classList.remove('exam-mode');};
};
// One persistent, accessible entry point. Dragging has a button alternative.
const chatLauncher=document.createElement('button');chatLauncher.className='justin-launcher';chatLauncher.id='justin-launcher';chatLauncher.setAttribute('aria-label','Mở hỏi đáp và tra cứu cùng Justin Mini');chatLauncher.innerHTML='<img src="assets/expressions/happy.png" alt=""><span>Hỏi Justin</span>';
document.body.append(chatLauncher);
const chatWindow=document.createElement('dialog');chatWindow.className='global-chat';chatWindow.innerHTML=`<div class="global-chat-head"><img id="chat-emotion" src="assets/expressions/listening.png" alt="Justin Mini lắng nghe"><div><h2>Justin Mini</h2><small id="global-chat-context">Học cùng bạn, có nguồn rõ ràng</small></div><button id="chat-position" class="icon-button" aria-label="Chuyển nút hỏi đáp sang bên trái hoặc phải">↔</button><button id="global-chat-close" class="icon-button" aria-label="Đóng hỏi đáp">×</button></div><div class="global-chat-messages" id="global-chat-messages"><p>Chọn tra cứu để tìm đoạn gốc kèm số trang. Hỏi AI sẽ gửi câu hỏi và trích đoạn liên quan tới nhà cung cấp đã cấu hình.</p></div><form id="global-chat-form"><label class="field">Bạn muốn hiểu phần nào?<textarea id="global-chat-query" maxlength="2000" rows="3" required placeholder="Ví dụ: cách triển khai bài Opinion…"></textarea></label><div><button class="button secondary" type="submit" data-chat-mode="search">Tra cứu nguồn</button><button class="button" type="submit" data-chat-mode="ai" id="global-ai-send">Hỏi AI</button></div><p id="global-ai-status" class="small-note" role="status">Đang kiểm tra kết nối AI…</p></form>`;
document.body.append(chatWindow);
const expressions=['happy','excited','thinking','listening','explaining','encouraging','proud','confused','surprised','sleepy'];expressions.forEach(name=>{const img=new Image();img.src='assets/expressions/'+name+'.png';});
function multiControl(q,e){const values=q.group.map(n=>e.answers[n-1]);return `<p class="small-note">Chọn ${q.group.length} phương án cho nhóm câu ${q.group.join(', ')}.</p>`+q.options.map(o=>`<label class="exam-option"><input type="checkbox" name="exam-multi" value="${esc(o.value)}" ${values.includes(o.value)?'checked':''}>${esc(o.label)}</label>`).join('');}
let emotionTimer,emotionPriority=0,emotionUntil=0;
function emotion(name,priority=1,duration=2200){if(!expressions.includes(name))return;const now=performance.now();if(now<emotionUntil&&priority<emotionPriority)return;emotionPriority=priority;emotionUntil=now+duration;clearTimeout(emotionTimer);chatLauncher.querySelector('img').src='assets/expressions/'+name+'.png';$('#chat-emotion').src='assets/expressions/'+name+'.png';emotionTimer=setTimeout(()=>{emotionPriority=0;chatLauncher.querySelector('img').src='assets/expressions/happy.png';},duration);}
let dragStart,dragged=false,position={x:null,y:null};try{position=JSON.parse(localStorage.getItem('justin-chat-position'))||position;}catch{}
function clampPosition(resized=false){if(position.x===null||innerHeight<200)return;if(resized&&innerWidth<=650)position.y=innerHeight-110;const rail=document.querySelector('.rail');const edge=innerWidth>650&&rail?rail.getBoundingClientRect().right+8:8;position.x=Math.max(edge,Math.min(innerWidth-96,position.x));position.y=Math.max(96,Math.min(innerHeight-100,position.y));chatLauncher.style.left=position.x+'px';chatLauncher.style.top=position.y+'px';chatLauncher.style.right='auto';chatLauncher.style.bottom='auto';}
clampPosition(true);addEventListener('resize',()=>clampPosition(true));
chatLauncher.onpointerdown=ev=>{dragStart={x:ev.clientX,y:ev.clientY,left:chatLauncher.getBoundingClientRect().left,top:chatLauncher.getBoundingClientRect().top};dragged=false;chatLauncher.setPointerCapture(ev.pointerId);};
chatLauncher.onpointermove=ev=>{if(!dragStart)return;const dx=ev.clientX-dragStart.x,dy=ev.clientY-dragStart.y;if(Math.hypot(dx,dy)>8)dragged=true;if(dragged){position={x:dragStart.left+dx,y:dragStart.top+dy};clampPosition();}};
chatLauncher.onpointerup=()=>{dragStart=null;if(dragged)localStorage.setItem('justin-chat-position',JSON.stringify(position));};chatLauncher.onpointercancel=()=>dragStart=null;
function openGlobalChat(){if(document.body.classList.contains('exam-mode')||[...Object.values(state?.exams||{}),...Object.values(state?.writingExams||{}),...Object.values(state?.readingSessions||{})].some(e=>e.mode==='exam'&&!e.submitted&&e.deadline>Date.now()/1000))return toast('Hỏi đáp được tắt cho tới khi nộp phiên thi đang làm.');const lessonId=location.hash.startsWith('#lesson/')?location.hash.split('/')[1]:null;$('#global-chat-context').textContent=lessonId?lessonById(lessonId)?.title:'Tra cứu toàn bộ học liệu';if(!chatWindow.open)chatWindow.show();$('#global-chat-query').focus();emotion('listening',2);}
chatLauncher.onclick=()=>{if(dragged){dragged=false;return;}openGlobalChat();};$('#global-chat-close').onclick=()=>chatWindow.close();$('#chat-position').onclick=()=>{position={x:position.x!==null&&position.x<innerWidth/2?innerWidth-105:12,y:innerHeight-110};clampPosition();localStorage.setItem('justin-chat-position',JSON.stringify(position));};
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();if(chatWindow.open)chatWindow.close();else openGlobalChat();}});
let chatBusy=false;
$('#global-chat-form').onsubmit=async ev=>{ev.preventDefault();if(chatBusy)return;const question=$('#global-chat-query').value.trim(),mode=ev.submitter?.dataset.chatMode||'search',lessonId=location.hash.startsWith('#lesson/')?location.hash.split('/')[1]:null;chatBusy=true;$('#global-chat-form').querySelectorAll('button').forEach(b=>b.disabled=true);const m=document.createElement('p');m.className='chat-user';m.textContent=question;$('#global-chat-messages').append(m);const result=document.createElement('div');result.className='chat-reply';result.textContent=mode==='ai'?'Justin đang đọc những đoạn liên quan…':'Đang tìm trong tài liệu gốc…';$('#global-chat-messages').append(result);emotion('thinking',3,80000);try{const r=await api(mode==='ai'?'/api/tutor':'/api/knowledge',mode==='ai'?{id:lessonId,question}:{query:question,lesson:lessonId});result.innerHTML=mode==='ai'?`<p class="ai-answer">${esc(r.text)}</p>`:'';if(!r.sources.length)result.textContent='Chưa tìm thấy nguồn phù hợp. Thử từ khóa tiếng Anh ngắn hơn hoặc mở tài liệu gốc.';for(const s of r.sources){if(s.text)result.insertAdjacentHTML('beforeend',sourceMarkup(s));else result.insertAdjacentHTML('beforeend',`<a target="_blank" rel="noopener" href="${s.href?.startsWith('/tutor-guide.html#')?esc(s.href):'/media/'+esc(s.id)+'#page='+(s.page||1)}">${esc(s.title)} · trang ${s.page||'?'}</a>`);}emotion('explaining',3);$('#global-chat-query').value='';}catch(err){result.textContent=err.message;emotion('encouraging',3);}finally{chatBusy=false;$('#global-chat-form').querySelectorAll('button').forEach(b=>b.disabled=false);$('#global-chat-messages').scrollTop=$('#global-chat-messages').scrollHeight;}};
api('/api/ai-status').then(r=>$('#global-ai-status').textContent=r.configured?'AI đã cấu hình. Khi hỏi AI, nội dung liên quan được gửi tới '+(r.provider==='gemini'?'Gemini':'OpenAI')+'.':'AI chưa kết nối. Tra cứu nguồn vẫn dùng được tại máy này.').catch(e=>$('#global-ai-status').textContent=e.message);
const historyButton=document.createElement('button');historyButton.className='text-link';historyButton.type='button';historyButton.textContent='Xem 5 cuộc hỏi đáp gần nhất';$('#global-chat-form').append(historyButton);
historyButton.onclick=async()=>{try{await refresh();const target=$('#global-chat-messages');target.innerHTML=(state.chatHistory||[]).slice(-5).map(h=>`<div class="chat-history"><p class="chat-user">${esc(h.query)}</p><small>${new Date(h.date*1000).toLocaleString('vi-VN')} · ${h.mode==='ai'?'Hỏi AI':'Tra cứu nguồn'}</small>${h.result.text?'<p class="ai-answer">'+esc(h.result.text)+'</p>':''}${(h.result.sources||[]).map(s=>s.text?sourceMarkup(s):`<a href="${s.href?.startsWith('/tutor-guide.html#')?esc(s.href):'/media/'+esc(s.id)+'#page='+(s.page||1)}" target="_blank" rel="noopener">${esc(s.title)}</a>`).join('')}</div>`).join('')||'<p>Chưa có hỏi đáp được lưu.</p>';}catch(e){toast(e.message);}};
const beforeLesson=lesson;
lesson=function(id){
 beforeLesson(id);const l=lessonById(id);if(!l)return;const prevCleanup=cleanup;let disposed=false;
 const overview=document.createElement('section');overview.className='panel lesson-overview';overview.innerHTML='<details><summary>Ý chính và nguồn để học bài này</summary><div id="lesson-overview-content">Đang tìm các trang liên quan…</div></details>';$('.lesson-utility').after(overview);
 const curated={ 'combined-writing-task-2-1':['Nêu rõ quan điểm ngay ở mở bài (slide Opinion, trang 2).','Chọn hoàn toàn đồng ý, không đồng ý hoặc đồng ý một phần; dàn ý tương ứng ở trang 4–5.','Viết mở bài, hai đoạn thân bài và kết luận; đề ví dụ ở trang 6.']};
 api('/api/lesson-overview',{id}).then(r=>{if(disposed)return;$('#lesson-overview-content').innerHTML=(curated[id]?'<ul>'+curated[id].map(t=>'<li>'+esc(t)+'</li>').join(''):'')+'<p class="small-note">Các trích đoạn dưới đây từ PDF đi kèm, không phải transcript hoặc tóm tắt nội dung video đã nghe.</p>'+r.sources.slice(0,3).map(sourceMarkup).join('')+(r.sources.length?'':'<p>Chưa có văn bản trích xuất phù hợp. Mở tài liệu gốc trong tab Tài liệu bài học.</p>');}).catch(e=>{if(!disposed)$('#lesson-overview-content').textContent=e.message;});
 if(l.video){const section=document.createElement('section');section.className='panel timestamp-panel';section.innerHTML=`<h3>Ghi nhớ đúng khoảnh khắc</h3><form id="timestamp-form"><label class="field">Ghi chú tại vị trí video<textarea id="timestamp-text" maxlength="2000" rows="2" required placeholder="Điều mình vừa hiểu hoặc muốn xem lại…"></textarea></label><button class="button secondary small">Lưu ghi chú tại mốc đang xem</button></form><div id="timestamp-notes"></div>`;$('.player-tools').after(section);function draw(){const notes=state.timestampNotes?.[id]||[];$('#timestamp-notes').innerHTML=notes.map(n=>`<article><button class="pill" data-ts="${n.at}">${clock(n.at)}</button><p>${esc(n.text)}</p></article>`).join('')||'<p class="small-note">Bấm vào một mốc đã lưu để quay lại đoạn video.</p>';section.querySelectorAll('[data-ts]').forEach(b=>b.onclick=()=>{$('#video').currentTime=Number(b.dataset.ts);$('#video').focus();});}$('#timestamp-form').onsubmit=async ev=>{ev.preventDefault();try{const n=await api('/api/timestamp-note',{id,at:$('#video').currentTime,text:$('#timestamp-text').value});((state.timestampNotes||={})[id]||=[]).push(n);$('#timestamp-text').value='';draw();toast('Đã lưu ghi chú tại '+clock(n.at));}catch(e){toast(e.message);}};draw();}
 cleanup=()=>{disposed=true;prevCleanup();};
};
const tabToken=crypto.randomUUID();let onlineBusy=false;
function renderOnline(o){if(!o)return;state.onlineStatus=o;const badge=$('#online-status');if(badge){badge.hidden=!accountReady||!accountInfo.user;badge.dataset.connected=navigator.onLine?'true':'false';badge.setAttribute('aria-label',navigator.onLine?'Đã đăng nhập · online':'Đã đăng nhập · mất kết nối');}const label=$('#online-text');if(label)label.textContent=navigator.onLine?'Online':'Mất kết nối';if($('#online-details'))$('#online-details').textContent=`Đã ghi nhận ${clock(o.seconds)}. ${o.reset?'Chu kỳ tiếp theo: '+new Date(o.reset*1000).toLocaleString('vi-VN',{timeZone:'Asia/Taipei'})+' (Asia/Taipei).':'Đăng nhập để tự động ghi nhận thời gian học.'}`;}
async function onlineHeartbeat(){if(!state||onlineBusy||!accountReady||!accountInfo.user||!navigator.onLine)return;onlineBusy=true;try{const o=await api('/api/online',{tab:tabToken,action:'on',active:!document.hidden&&document.hasFocus()});renderOnline(o);}catch{}finally{onlineBusy=false;}}
setInterval(()=>onlineHeartbeat(),15000);document.addEventListener('visibilitychange',()=>onlineHeartbeat());window.addEventListener('focus',()=>onlineHeartbeat());window.addEventListener('blur',()=>onlineHeartbeat());window.addEventListener('pagehide',()=>{if(state&&accountReady&&accountInfo.user)navigator.sendBeacon('/api/online',new Blob([JSON.stringify({tab:tabToken,active:false})],{type:'application/json'}));});
const inheritedRoute=route;
document.querySelector('.skip-link').onclick=ev=>{ev.preventDefault();$('#app').focus();};
route=function(){
 const [screen='home',...parts]=location.hash.slice(1).split('/'),views={pet,rewards,writing:writingView,speaking:speakingView,knowledge:knowledgeView,settings,'vocab-practice':vocabPractice,'vocab-matching':vocabMatching,'vocab-images':()=>vocabIllustrationGame(false),'vocab-context':()=>vocabIllustrationGame(true)};
 if(chatWindow.open)chatWindow.close();
 if(views[screen]){cleanup();cleanup=()=>{};document.body.dataset.screen=screen;document.body.classList.remove('exam-mode');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===screen));$('#page-label').textContent=worldNav[screen]||'Không gian học';$('.rail').classList.remove('open');views[screen]();window.scrollTo(0,0);}else inheritedRoute();
 applySettings();renderOnline(state.onlineStatus);
 const activeExam=[...Object.values(state.exams||{}),...Object.values(state.writingExams||{})].some(e=>e.mode==='exam'&&!e.submitted&&e.deadline>Date.now()/1000);
 chatLauncher.hidden=screen==='test'&&parts.at(-1)==='exam'||activeExam;
 if(screen==='test'&&parts.at(-1)==='exam')chatLauncher.hidden=true;
 document.querySelectorAll('img[alt]').forEach(img=>{img.alt=img.alt.replaceAll('Justin Mini','Justin Mini');});
};


